; Video decoder of Bad Apple!! for SAPI-1 (docs/format.md).
;
; vdec_frame: decode one frame body (tracks of XOR intervals, row clears) onto the CPU page of CGA-1V.
;   in:  BC = frame body (in RAM, after the 1 B frame header), CGA-1V mapped (C000h), CPU page selected
;   out: BC = after the END opcode; AF, DE, HL destroyed
; The handlers of the opcodes are generated by tools/mkvdec.py (sapi/gen/vdec.asm, from 1000h). Every handler
; ends with the dispatch of the next opcode, END returns.

vdec_frame:
	ld a,(bc)
	inc bc
	ld l,a
	ld h,HI_VJT
	ld h,(hl)
	jp (hl)

vtstart:
	dw 0				; DE of the start of the last track (TRACKR adds to it)

; CLR: 2 B address of the first row (byte 0 of the picture row), 1 B rows, 1 B colour. Fills 64 B per row
; (stride 80) with PUSH; interrupts are enabled between rows (SP back on the stack for that).
vclr:
	ld a,(bc)
	inc bc
	ld l,a
	ld a,(bc)
	inc bc
	ld h,a
	ld de,64
	add hl,de			; PUSH fills down from the end of the row
	ld a,(bc)
	inc bc
	push af				; rows
	ld a,(bc)
	inc bc
	ld e,a
	ld d,a
	ld (vclr_bc),bc
	pop af
	ld (vclr_sp),sp
	ld bc,80
	di
.vclr_row:
	ld sp,hl
	rept 32
	push de
	endm
	add hl,bc
	ld sp,(vclr_sp)
	ei
	dec a				; an interrupt can come after this instruction
	di
	jr nz,.vclr_row
	ei
	ld bc,(vclr_bc)
	ld a,(bc)			; dispatch
	inc bc
	ld l,a
	ld h,HI_VJT
	ld h,(hl)
	jp (hl)

vclr_sp:
	dw 0
vclr_bc:
	dw 0
